import{_ as i,c as t,o as n,ag as a}from"./chunks/framework.CQuhCYrb.js";const m=JSON.parse('{"title":"Series Funding Packet","description":"","frontmatter":{"title":"Series Funding Packet"},"headers":[],"relativePath":"general/series-funding-packet.md","filePath":"general/series-funding-packet.md","lastUpdated":null}'),l={name:"general/series-funding-packet.md"};function s(r,e,o,u,d,p){return n(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="series-funding-packet" tabindex="-1">Series Funding Packet <a class="header-anchor" href="#series-funding-packet" aria-label="Permalink to &quot;Series Funding Packet&quot;">​</a></h1><h2 id="funding-request-review-workflow" tabindex="-1">Funding Request Review Workflow <a class="header-anchor" href="#funding-request-review-workflow" aria-label="Permalink to &quot;Funding Request Review Workflow&quot;">​</a></h2><p><strong>Purpose</strong>: Ensure Funding Request is consistent with Series documentation and meets standards for approval.</p><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ul><li><p>Ensure Task is in the OPCEN RFS Tracker and comment on tracker to let the team know that the review is beginning.</p></li><li><p>Upload Funding Request to Portal in the development folder Funding &amp; Contracting Documents.</p><ul><li>Name file: <em>SERIES NAME_FUNDING REQUEST_YEARMONTH</em>.</li></ul></li><li><p>Review guidance and SOP saved on SIPR portal (SOCSOUTH PSYOP page - In Development - References - Funding Request Review Docs).</p></li><li><p>Read Funding Request.</p></li><li><p>Create Comments version.</p><ul><li>Name file: <em>SERIES NAME_FUNDING REQUEST_YEARMONTH_Comments</em>.</li></ul></li><li><p>Confirm Formatting.</p></li><li><p>Review and correct Funding Request.</p></li><li><p>Submit for review:</p><ul><li>OPCEN Leadership.</li><li>Company Leadership.</li></ul></li><li><p>Leadership will return to the team.</p></li></ul><h3 id="specific-steps" tabindex="-1">Specific Steps <a class="header-anchor" href="#specific-steps" aria-label="Permalink to &quot;Specific Steps&quot;">​</a></h3><ul><li><p>Ensure Task is in the OPCEN RFS Tracker and comment on tracker to let the team know that the review is beginning.</p><ul><li>If the task is not in the RFS Tracker, add it and include the requester&#39;s email and team appropriately.</li><li>When it is on the RFS tracker, assign yourself and change the status of the RFS as you work on it.</li></ul></li><li><p>Upload Funding Request to Portal in the development folder Funding &amp; Contracting Documents.</p><ul><li>Name file: <em>SERIES NAME_FUNDING REQUEST_YEARMONTH</em>.</li></ul></li><li><p>Review guidance and SOP saved on SIPR portal (SOCSOUTH PSYOP page - In Development - References - Funding Request Review Docs).</p></li><li><p>Read Funding Request.</p><ul><li>The document may be divided into Funding Request and Statement of Work (SOW). These can be all in one document or sent separately.</li></ul></li><li><p>Create Comments version.</p><ul><li>Name file: <em>SERIES NAME_FUNDING REQUEST_YEARMONTH_Comments</em>.</li></ul></li><li><p>Confirm Formatting.</p><ul><li>Ensure formatting matches the SOP.</li><li>If the SOW was sent separately, combine it with the Funding Request.</li></ul></li><li><p>Review and correct Funding Request.</p><ul><li>Check Admin data: <em>Note: &quot;MISO VOICE&quot; does not refer to VOICE at SOCSOUTH; it&#39;s in reference to VOICE funding source.</em></li><li>Technical Exhibit: use a calculator to verify costs. Assess how close the cumulative total cost must be.</li></ul></li></ul><p>[Up] [Required]</p>',8)])])}const h=i(l,[["render",s]]);export{m as __pageData,h as default};
